package com.solarmind.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="solar_panels",uniqueConstraints=@UniqueConstraint(name="uk_panels_brand_model",columnNames={"brand","model"}),indexes={@Index(name="idx_panels_brand",columnList="brand"),@Index(name="idx_panels_wattage",columnList="wattage")}) public class SolarPanel { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String brand,model; private Integer wattage; private BigDecimal dailyOutput,monthlyOutput,efficiency,vmpp,impp,weight; private String dimensions,productLink; protected SolarPanel(){} public SolarPanel(String brand,String model,Integer wattage,BigDecimal dailyOutput,BigDecimal monthlyOutput,BigDecimal efficiency,BigDecimal vmpp,BigDecimal impp,String dimensions,BigDecimal weight,String productLink){this.brand=brand;this.model=model;this.wattage=wattage;this.dailyOutput=dailyOutput;this.monthlyOutput=monthlyOutput;this.efficiency=efficiency;this.vmpp=vmpp;this.impp=impp;this.dimensions=dimensions;this.weight=weight;this.productLink=productLink;} public Long getId(){return id;} public String getBrand(){return brand;} public String getModel(){return model;} public Integer getWattage(){return wattage;} public BigDecimal getDailyOutput(){return dailyOutput;} public BigDecimal getMonthlyOutput(){return monthlyOutput;} public BigDecimal getEfficiency(){return efficiency;} public BigDecimal getVmpp(){return vmpp;} public BigDecimal getImpp(){return impp;} public BigDecimal getWeight(){return weight;} public String getDimensions(){return dimensions;} public String getProductLink(){return productLink;} }
